{
  "path": "supabase/migrations/20260801155605_create_todos.sql",
  "contents": "create table public.todos (
  id bigint generated by default as identity primary key,
  task text not null,
  is_complete boolean not null default false,
  created_at timestamptz not null default now()
);

alter table public.todos enable row level security;

-- Todos are readable by signed-in users, but are not writable through the Data API.
create policy "Authenticated users can read todos"
  on public.todos
  for select
  to authenticated
  using (true);

revoke all on table public.todos from anon, authenticated;
grant select on table public.todos to authenticated;

-- Identity sequences are not needed by clients while writes are disabled.
revoke all on sequence public.todos_id_seq from anon, authenticated;
"
}

